 SELECT CONCAT(tusr.user_fname," ",tusr.user_lname) AS A02,  SUM(tras.imported)  AS A06,  SUM(tras.shortlisted)  AS A15,  SUM(tras.appointment)  AS A09,  SUM(tras.interview)  AS A10,  SUM(tras.messages)  AS A11,  SUM(tras.phone)  AS A12,  SUM(tras.email_sent)  AS A08 FROM tp_cr_activity_summary AS tras JOIN tp_users AS tusr ON (tras.user_id = tusr.user_id)  WHERE 1 @@  GROUP BY tras.user_id ORDER BY tras.user_id